 src=p/'src/DiophantineConsistency'/(n+'.lean');s=src.read_text();ref=root/'research/nine-seed38-jones-named-equality-retry03/src/DiophantineConsistency'/('Norm38Macro'+suf+'.lean');assert s==ref.read_text().replace('Norm38','Sign33').replace('38','33').replace('5 ^ 39','5 ^ 34') and sha(src)==sha(repo/e['source'])==e['source_sha256'] and e['module']=='DiophantineConsistency.'+n and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==e['imports'] and not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit|native_decide)\b',s)
