s=(p/'src/DiophantineConsistency/Sign33MacroNamedEquality.lean').read_text();assert all(t in s for t in ('theorem recipe_eq_expression_eval {R : Type*} [CommRing R] (a : Fin 9 → R)','Sign33MacroRecipe.recipe.values a (Fin.last 44) = Sign33IPRAEndpoint.expression.evalRing a','recipe_eq_refined a','vars_eq_named','Sign33NamedFormula.eval_current a'))
r=(p/'run.py').read_text();assert all(t in r for t in ("if not sys.flags.isolated or not sys.flags.no_site or sys.flags.optimize", "need(not OUT.exists(),'output exists')", "need(not sys.argv[1:],'unexpected arguments')", "'-M2800'",'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1',"'another Lean process is active'","shutil.disk_usage('/tmp').free>=5_000_000_000",'candidate target union collision','candidate target fallback collision','guard(deps)==row[\'direct_guard\']','final source drift','final provider drift','final overlay drift')) and r.count('check_external_syntax()')==3
survey=p/'provider-survey.py';x=subprocess.run([sys.executable,'-I','-S','-B',str(survey)],capture_output=True,text=True,timeout=360);assert x.returncode==0 and not x.stderr;d=json.loads(x.stdout);assert d['status']=='PASS_POINT_IN_TIME_PROVIDER_SURVEY' and len(d['union'])==1388
for n in names:
 for suffix in ('.olean','.olean.private','.olean.server','.ir','.ilean','.olean.hash','.olean.private.hash','.olean.server.hash','.ir.hash','.ilean.hash'):assert 'DiophantineConsistency/'+n+suffix not in d['union']
x=subprocess.run([sys.executable,'-I','-S','-B',str(p/'run.py'),'--preflight'],capture_output=True,text=True,timeout=360);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
